package com.fakenewsdetector.controller;
import com.fakenewsdetector.dto.AuthDtos.*; import com.fakenewsdetector.entity.User; import com.fakenewsdetector.service.AuthService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService service;public AuthController(AuthService s){service=s;} @PostMapping("/register")public ResponseEntity<?> register(@Valid @RequestBody Register r){return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("success",true,"data",service.register(r)));}@PostMapping("/login")public Map<String,Object> login(@Valid @RequestBody Login l){return Map.of("success",true,"data",service.login(l));}@GetMapping("/me")public Map<String,Object> me(@AuthenticationPrincipal User u){return Map.of("success",true,"data",service.current(u));}}
